import { FOCUS } from "./kinetic";
import { addText, TYPE_MOTION_START_MAX_MS, type Clip, type TextOverlay, type Timeline, type Voiceover } from "./timeline";
import { captionsWithWords, hasSpeech, type Transcript, type TranscriptWord } from "./transcript";

/**
 * A spoken voiceover (ADR 0099): a short script in a chosen voice, over the
 * footage, with captions on its words. The voice is generated by the voice
 * Worker (infra/cloudflare/voice, Workers AI) and transcribed by the render
 * worker, so the captions and the music's dips land on the words as spoken.
 */

/** The voices offered, Deepgram Aura-2 on Workers AI (`@cf/deepgram/aura-2-en`). Australian first: ReelWalk is Australia-first (ADR 0081). */
export const VOICES = [
  { id: "aura-2:theia", name: "Theia", description: "Australian woman, expressive and sincere" },
  { id: "aura-2:hyperion", name: "Hyperion", description: "Australian man, warm and caring" },
  { id: "aura-2:thalia", name: "Thalia", description: "American woman, clear and energetic" },
  { id: "aura-2:apollo", name: "Apollo", description: "American man, confident and casual" },
  { id: "aura-2:aurora", name: "Aurora", description: "American woman, cheerful" },
  { id: "aura-2:atlas", name: "Atlas", description: "American man, enthusiastic and friendly" },
  { id: "aura-2:athena", name: "Athena", description: "American woman, calm and professional" },
  { id: "aura-2:zeus", name: "Zeus", description: "American man, deep and trustworthy" },
  { id: "aura-2:pandora", name: "Pandora", description: "British woman, smooth and calm" },
  { id: "aura-2:draco", name: "Draco", description: "British man, warm baritone" },
] as const;

export type VoiceId = (typeof VOICES)[number]["id"];
export const DEFAULT_VOICE: VoiceId = "aura-2:theia";

/** The longest script the voice Worker speaks in one request. */
export const VOICEOVER_MAX_CHARS = 400;

export function isVoiceId(value: unknown): value is VoiceId {
  return VOICES.some((voice) => voice.id === value);
}

export function voiceName(id: string): string {
  return VOICES.find((voice) => voice.id === id)?.name ?? id;
}

type CaptionText = Omit<TextOverlay, "endMs" | "animation"> & { endMs: number; animation: TextOverlay["animation"] };

/** Captions are texts with this id prefix: setting the voiceover again replaces them, taking it off removes them. */
export const VOICEOVER_TEXT_PREFIX = "vo-";

/** The voiceover's words in reel time, for the music's dips and the captions. */
export function voiceoverWords(voiceover: Voiceover, transcript: Transcript | null | undefined): TranscriptWord[] {
  if (!hasSpeech(transcript)) return [];
  return transcript.words.map((word) => ({ ...word, s: voiceover.atMs + word.s, e: voiceover.atMs + word.e }));
}

/** The voiceover as a clip-shaped window over its own file, so the clip caption engine times its phrases. */
function asClip(transcript: Transcript): Clip {
  const endMs = Math.max(...transcript.words.map((word) => word.e), 0) + 400;
  return { sourceStartMs: 0, sourceEndMs: endMs, speed: 1 } as Clip;
}

/**
 * Captions for the voiceover: short phrases from its own words, each word
 * coming into focus as it is said (ADR 0092), low in the frame and clear of
 * Instagram's caption zone. Ids start with `vo-`.
 */
export function voiceoverCaptions(voiceover: Voiceover, transcript: Transcript, style: { y?: number; size?: number } = {}): CaptionText[] {
  if (!hasSpeech(transcript)) return [];
  return captionsWithWords(transcript, asClip(transcript), voiceover.atMs).map((phrase, index) => {
    const wordsMs = phrase.wordStartsMs.map((ms) => Math.max(0, Math.min(TYPE_MOTION_START_MAX_MS, ms - phrase.startMs)));
    return {
      id: `${VOICEOVER_TEXT_PREFIX}${index}`,
      text: phrase.text,
      startMs: phrase.startMs,
      endMs: phrase.endMs,
      x: 0.5,
      y: style.y ?? 0.62,
      style: "elegant",
      color: "#ffffff",
      size: style.size ?? 1,
      animation: "none",
      kinetic: { preset: "focus", startMs: 0, durationMs: Math.max(100, Math.min(10_000, (wordsMs[wordsMs.length - 1] ?? 0) + FOCUS.arriveMs)), wordsMs },
    } as CaptionText;
  });
}

/** The reel with `voiceover` set (or taken off) and its captions replaced: none when `captions` is false or there is no transcript. */
export function withVoiceover(timeline: Timeline, voiceover: Voiceover | null, transcript: Transcript | null | undefined, captions: boolean): Timeline {
  const texts = timeline.texts.filter((text) => !text.id.startsWith(VOICEOVER_TEXT_PREFIX));
  if (!voiceover) {
    const rest = { ...timeline, texts };
    delete rest.voiceover;
    return rest;
  }
  let next: Timeline = { ...timeline, texts, voiceover };
  if (captions && transcript) for (const caption of voiceoverCaptions(voiceover, transcript)) next = addText(next, caption);
  return next;
}
